    59  static int coolkey_detect_card(sc_pkcs15_card_t *p15card)
    60  {
    61          sc_card_t *card = p15card->card;
    62
    63          SC_FUNC_CALLED(card->ctx, SC_LOG_DEBUG_VERBOSE);
    64          if (card->type < SC_CARD_TYPE_COOLKEY_GENERIC
    65                  || card->type >= SC_CARD_TYPE_COOLKEY_GENERIC+1000)
    66                  return SC_ERROR_INVALID_CARD;
    67          return SC_SUCCESS;
    68  }
