    70  static int
    71  coolkey_get_object(sc_card_t *card, unsigned long object_id, sc_cardctl_coolkey_object_t **obj) {
    72          sc_cardctl_coolkey_find_object_t fobj;
    73          int r;
    74
    75          fobj.type = SC_CARDCTL_COOLKEY_FIND_BY_ID;
    76          fobj.find_id = object_id;
    77          fobj.obj = NULL;
    78          r = sc_card_ctl(card, SC_CARDCTL_COOLKEY_FIND_OBJECT, &fobj);
    79          if (r < 0) {
    80                  return r;
    81          }
    82          *obj = fobj.obj;
    83          return SC_SUCCESS;
    84  }
