    90  static int
    91  coolkey_get_attribute(sc_card_t *card, sc_cardctl_coolkey_object_t *obj, CK_ATTRIBUTE_TYPE type, const u8 **val, size_t *val_len, u8 *data_type) {
    92          sc_cardctl_coolkey_attribute_t attribute;
    93          int r;
    94
    95          attribute.object = obj;
    96          attribute.attribute_type = type;
    97
    98          r = sc_card_ctl(card, SC_CARDCTL_COOLKEY_GET_ATTRIBUTE, &attribute);
    99          if (r < 0) {
   100                  return r;
   101          }
   102          *val = attribute.attribute_value;
   103          *val_len = attribute.attribute_length;
   104          if (data_type) {
   105                  *data_type = attribute.attribute_data_type;
   106          }
   107          return SC_SUCCESS;
   108  }
