   147  static int
   148  coolkey_get_attribute_ulong(sc_card_t *card, sc_cardctl_coolkey_object_t *obj, CK_ATTRIBUTE_TYPE type, CK_ULONG *value)
   149  {
   150          const u8 *val;
   151          size_t val_len;
   152          u8 data_type;
   153          int r;
   154
   155          r  = coolkey_get_attribute(card, obj, type, &val, &val_len, &data_type);
   156          if (r < 0) {
   157                  return r;
   158          }
   159          if ((data_type != SC_CARDCTL_COOLKEY_ATTR_TYPE_ULONG) &&
   160              (val_len != sizeof(CK_ULONG))) {
   161                  return SC_ERROR_CORRUPTED_DATA;
   162          }
   163          *value = bebytes2ulong(val);
   164          return SC_SUCCESS;
   165  }
