   167  static int
   168  coolkey_get_attribute_boolean(sc_card_t *card, sc_cardctl_coolkey_object_t *obj, CK_ATTRIBUTE_TYPE attr_type)
   169  {
   170          int r;
   171          const u8 *val;
   172          size_t val_len;
   173
   174          r = coolkey_get_attribute(card, obj, attr_type, &val, &val_len, NULL);
   175          if (r < 0) {
   176                  /* attribute not valid for this object, set boolean to false */
   177                  return 0;
   178          }
   179          if ((val_len == 1) && (*val == 1)) {
   180                  return 1;
   181          }
   182          return 0;
   183  }
