   714  int
   715  sc_pkcs15emu_coolkey_init_ex(sc_pkcs15_card_t *p15card,
   716                  struct sc_aid *aid)
   717  {
   718          sc_card_t      *card = p15card->card;
   719          sc_context_t    *ctx = card->ctx;
   720          int rv;
   721
   722          LOG_FUNC_CALLED(ctx);
   723
   724          rv = coolkey_detect_card(p15card);
   725          if (rv)
   726                  LOG_FUNC_RETURN(ctx, SC_ERROR_WRONG_CARD);
   727          rv = sc_pkcs15emu_coolkey_init(p15card);
   728
   729          LOG_FUNC_RETURN(ctx, rv);
   730  }
